INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaun-palmers-pro-snowboarder-usa', 'GAMEBOYCOLOR', 'Shaun Palmer''s Pro Snowboarder (USA)', '2001', 'Sports', 'Neversoft', '2', 'Extreme sports snowboarding', 'Snowboarding simulation with tricks and high-speed racing.', 'Land insane combos and win the pro snowboarding tour.', 'High-octane extreme sports.', 'Shaun Palmer''s Pro Snowboarder offers tight controls and fluid animations. Shred the slopes and unlock new gear in this extreme GBC title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-devil-children---aka-no-sho-japan', 'GAMEBOYCOLOR', 'Shin Megami Tensei Devil Children - Aka no Sho (Japan)', '2002', 'RPG', 'ATLUS', '1', 'Monster-collecting RPG', 'Monster-collecting RPG with negotiation and fusion.', 'Save the demon world by recruiting and evolving monsters.', 'Kid-friendly Megami Tensei (Aka).', 'Devil Children: Aka no Sho features exclusive demons and a deep story. Use the "Devil Rise" system to grow your army on GBC.');
