INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zook-hero-z', 'GAMEBOYCOLOR', 'Zook Hero Z', '2000', 'Action', 'Unknown', '1', 'Action platformer', 'Side-scrolling action platformer (Unlicensed Bootleg).', 'Defeat the robot army in this Megaman-inspired quest.', 'Rare unlicensed action clone.', 'Zook Hero Z (or Zook Z) is a high-quality Chinese bootleg. It plays similarly to Mega Man X, featuring impressive sprites and tough bosses.');